import Axios from "./axios";

export const GetConfig = () => {
  const url = "/config.json";
  return Axios.get(url, {});
};
// params :
// id 控制舵id  angle 方向 switch 是否开启吸盘
export const setManipulator = (config, params) => {
  let url = "/use_arm";
  return Axios({
    url: config.ip + url,
    method: "POST",
    data: params
  });
};
// 获取 方向舵 角度
export const getAngle = (config, id) => {
  let url = "/get_arm";
  return Axios({
    url: config.ip + url,
    method: "GET",
    params: { id: id }
  });
};
// 获取吸盘配置信息
export const getSuckerConfig = (config) => {
  let url = "/get_conf";
  return Axios({
    url: config.url + url,
    method: "GET"
  });
};
// 设置吸盘配置
export const setSuckerConfig = (suckerConfig, config) => {
  let url = "/change_conf";
  return Axios({
    url: config.url + url,
    method: "POST",
    data: suckerConfig
  });
};
