<template>
  <div class="header">
    <div class="left"></div>
    <div class="center">
      <span class="center-text">{{ name }}</span>
      <span class="mt_15">{{ version }}</span>
    </div>
    <div class="right">
      <span>{{ time | getTime(true) }}</span>
    </div>
  </div>
</template>

<script>
export default {
  name: "VHeader",
  props: ["name", "version"],
  data() {
    return {
      time: new Date()
    };
  },
  created() {
    this.getTime();
    this.reload();
  },
  methods: {
    getTime() {
      setInterval(() => {
        this.time = new Date();
      }, 1000);
    },
    reload() {
      setInterval(() => {
        location.reload();
      }, 10800000);
    }
  }
};
</script>

<style lang="less" scoped>
.header {
  height: 60px;
  display: flex;
  background: #3879fb;
  color: #ffffff;
  .left,
  .right {
    width: 25%;
    height: 100%;
    padding: 0 70px;
    display: flex;
    align-items: center;
    justify-content: flex-end;
    font-size: 15px;
  }
  .center {
    width: 50%;
    height: 100%;
    display: flex;
    align-items: center;
    justify-content: center;
    position: relative;
    font-size: 19px;
    font-weight: 500;
    .center-text {
      font-size: 30px;
    }
    .mt_15 {
      margin-top: 15px;
    }
  }
}
</style>
