<template>
  <div id="app">
    <VHeader :name="title" :version="version"></VHeader>
    <div class="main">
      <div class="main-left">
        <!-- 摄像头信息 -->
        <VBorder class="main-left-top" :title="'检测区域'">
          <div class="detection-result">
            <img :src="config.url + '/img'" class="image detection" />
          </div>
        </VBorder>
        <!-- 机械臂控制模块 -->
        <VBorder class="main-left-center" :title="'机械臂手动控制'">
          <div class="operation-button">
            <span @click="btnClick('1')" :class="{'active': active === '1'}">1</span>
            <span @click="btnClick('2')" :class="{'active': active === '2'}">2</span>
            <span @click="btnClick('3')" :class="{'active': active === '3'}">3</span>
            <span @click="btnClick('4')" :class="{'active': active === '4'}">4</span>
            <!-- <span @click="btnClick('5')" :class="{'active': active === '5'}">5</span> -->
          </div>
          <div class="operation-slider">
            <span class="btn left" @click="step">{{ active === "1" ? "左" : "上"}}</span>
            <div class="slider">
              <el-slider v-model="radian" @change="sliderChange" :max="active === '5' ? 270 : 180" :color="'#167aff'"></el-slider>
            </div>
            <span class="btn right" @click="next">{{ active === "1" ? "右" : "下"}}</span>
          </div>
          <div class="slider-info">当前关节：<span class="text-value">{{ active }} </span> 当前角度： <span class="text-value">{{ radian }}</span></div>
          <div class="button">
            <el-button size="mini" :type="isGrab ? 'success' : 'primary'" @click="sucker('grab')">抓取</el-button>
            <el-button size="mini" @click="sucker('discharge')">释放</el-button>
          </div>
        </VBorder>
        <!-- 吸盘控制模块 -->
        <VBorder class="main-left-footer" :title="'机械臂参数设置'">
          <!-- <div class="footer-item">
            <span class="label">吸盘抓力：</span>
            <div class="operation-button">
              <span @click="suckerClick('2500')" :class="{'active': suckerValue === '2500'}">大</span>
              <span @click="suckerClick('2100')" :class="{'active': suckerValue === '2100'}">中</span>
              <span @click="suckerClick('1700')" :class="{'active': suckerValue === '1700'}">小</span>
            </div>
          </div> -->
          <div class="footer-item">
            <span class="label">抓取位置：</span>
            <el-slider v-model="grabPosition" @change="setConfig" :max="180" :color="'#167aff'"></el-slider>
            <span class="slider-value">{{grabPosition}}</span>
          </div>
          <div class="footer-item">
            <span class="label">释放位置：</span>
            <el-slider v-model="releasePosition" @change="setConfig" :max="180" :color="'#167aff'"></el-slider>
            <span class="slider-value">{{releasePosition}}</span>
          </div>
          <div class="footer-item">
            <span class="label">抓取延时：</span>
            <el-input class="grabTimeout" placeholder="请输入" v-model="grabTimeout" size="mini" onkeyup="value=value.replace(/^(0+)|[^\d]+/g,'')" @change="setConfig"></el-input>
            <span class="tip">秒</span>
          </div>
        </VBorder>
      </div>
      <div class="main-center">
        <div class="main-center-top">
          <div class="main-center-top-left">
            <VBorder class="main-center-item active" :title="'原始图片'">
              <div class="detection-result">
                <img class="image" :src="originalImg" />
              </div>
            </VBorder>
            <VBorder class="main-center-item center_item_bt" :title="'检测结果'">
              <span slot="title" class="tip" v-if="testingImg" >（{{ testingText }}）</span>
              <div  class="detection-result">
                <img class="image" v-if="testingImg" :src="testingImg" />
                <span v-if="!testingImg" class="text">未检测到缺陷</span>
              </div>
            </VBorder>
          </div>
          <div class="main-center-center">
            <VBorder class="main-center-item" :title="'最近检测结果图'">
              <div class="img" v-for="(img, $index) in imgHistory" :key="$index">
                <div class="img_blck">
                  <img @click="imgDetail(img)" :src="img.img" >
                </div>
                <p :title="img.text">{{ img.text }}</p>
              </div>
            </VBorder>
          </div>
          <div class="main-center-top-right">
            <VBorder class="main-center-item padding-top-none" :title="'检测统计'">
              <div class="echarts">
                  <div class="echarts-item">
                    <div class="echarts-item-content performance">
                      <div class="performance-item">
                        <div class="echarts-pie" ref="echartsPie"></div>
                      </div>
                      <div class="performance-item flex_descipe">
                        <p class="performance-item-title mt_20">
                          <span>平均延时（ms）: </span><span>{{ statisticsInfo.time }}</span>
                        </p>
                        <p class="performance-item-title">
                          <span>平均准确率（%）: </span><span>{{ statisticsInfo.averageScore }}</span></p>
                      </div>
                    </div>
                  </div>
                  <div class="echarts-item">
                    <h6 class="echarts-item-title">缺陷分布统计<span>（个）</span></h6>
                    <div class="echarts-item-content" ref="defect"></div>
                  </div>
                  <div class="echarts-item">
                    <h6 class="echarts-item-title">当月内缺陷分布统计<span>（个）</span></h6>
                    <div class="echarts-item-content" ref="statistics"></div>
                  </div>
                  <div class="echarts-item">
                    <h6 class="echarts-item-title">七日内缺陷总量统计<span>（个）</span></h6>
                    <div class="echarts-item-content" ref="total"></div>
                  </div>
              </div>
            </VBorder>
          </div>
        </div>
      </div>
    </div>
    <el-dialog :visible.sync="dialog.visible" class="preview-dialog">
      <div class="dialog-img">
        <img :src="dialog.img">
      </div>
    </el-dialog>
  </div>
</template>

<script>
import VHeader from "./components/Header.vue";
import VBorder from "./components/Border.vue";
import * as echarts from "echarts/lib/echarts";
import "echarts/lib/chart/line";
import "echarts/lib/chart/bar";
import "echarts/lib/chart/pie";
// 引入提示框组件、标题组件、工具箱组件。
import "echarts/lib/component/tooltip";
import "echarts/lib/component/legend";
import "echarts/lib/component/title";
import {
  GetConfig,
  setManipulator,
  getAngle,
  getSuckerConfig,
  setSuckerConfig,
  getHistory,
  getOriginalImg,
  getTestingImg,
  getAllNum,
  getStatistics,
  getMonthNum,
  getDaysNum,
} from "./js/api";
export default {
  name: "App",
  data() {
    return {
      title: "",
      version: "",
      active: "1",
      suckerValue: "2500",
      grabPosition: 0,
      grabTimeout: "",
      originalImg: "",
      testingImg: "",
      releasePosition: 0,
      radian: 0,
      config: {},
      imgHistory: [],
      dialog: {
        visible: false,
        img: ""
      },
      statistics: null,
      isGrab: false,
      echartsOption: {
        color: ["#1479ff"],
        textStyle: { color: "#999999" },
        grid: { top: 10, left: 40, right: 0, bottom: 20 },
        xAxis: {
          type: "category",
          show: true,
          data: [],
          axisTick: { show: false },
          axisLine: { show: false }
        },
        yAxis: {
          type: "value",
          axisLine: { show: false },
          axisTick: { show: false },
          splitLine: { lineStyle: { color: "#e5e5e5" } },
        },
        tooltip: {
          trigger: 'item'
        },
        series: [{
          data: [{value: 0}, {value: 0}, {value: 0}, {value: 0}, {value: 0}],
          type: "bar"
        }]
      },
      defectEcharts: null,
      statisticsEcharts: null,
      totalEcharts: null,
      pieEcharts: null,
      keys: {},
      statisticsInfo: {
        time: "",
        averageScore: "",
        defectNum: "",
        totalNum: ""
      }
    };
  },
  async mounted() {
    this.config = await GetConfig();
    this.title = this.config.title;
    this.version = this.config.version;
    this.btnClick(this.active);
    const result = await getSuckerConfig(this.config);
    this.suckerValue = result[0].speed;
    this.grabPosition = Number(result[0].grab_position);
    this.releasePosition = Number(result[0].release_position);
    this.grabTimeout = result[0].time;
    this.keys = result[0].defect_name;
    this.echartsOption.xAxis.data = Object.values(this.keys);
    this.getImgList(true);
    this.getOriginalImg(true);
    this.getTestingImg(true);
    this.getStatistics();
    this.getDefectNum();
    this.getMonthNum();
    this.getTotalNum();
  },
  components: {
    VHeader,
    VBorder
  },
  methods: {
    // 选取舵机
    async btnClick(index) {
      this.active = index;
      const result = await getAngle(this.config, index);
      this.radian = Number(result);
    },
    // 舵机方向调节
    sliderChange(val) {
      this.manipulatorControl(this.active, String(val));
    },
    step() {
      this.radian -= 1;
      this.manipulatorControl(this.active, String(this.radian));
    },
    next() {
      this.radian += 1;
      this.manipulatorControl(this.active, String(this.radian));
    },
    // 吸盘选择
    suckerClick(val) {
      this.suckerValue = val;
      this.setConfig();
    },
    sucker(type) {
      if (type === "grab") {
        this.isGrab = true;
      } else {
        this.isGrab = false;
      }
      setManipulator(this.config, {
        id: "",
        angle: "",
        switch: String(this.isGrab)
      });
    },
    setConfig() {
      let config = {
        grab_position: String(this.grabPosition),
        speed: this.suckerValue,
        release_position: String(this.releasePosition),
        time: this.grabTimeout
      }
      setSuckerConfig(config, this.config);
    },
    // 
    async getImgList(type) {
      const result = await getHistory(this.config);
      if (result && result.length) {
        this.imgHistory = result.map(_r => {
          let item = { img: _r.img, text: "" };
          let text = []
          _r.name.forEach(r => {
            text.push(this.keys[r[0]]);
          });
          item.text = text.join("，");
          return item;
        });
      }
      if (type) {
        setTimeout(() => {
          this.getImgList(true);
        }, 3000);
      }
    },
    imgDetail(img) {
      this.dialog.visible = true;
      this.dialog.img = img.img;
    },
    manipulatorControl(id, direction) {
      setManipulator(this.config, {
        id: id,
        angle: direction,
        switch: ""
      });
    },
    // 获取原始图片
    getOriginalImg(type) {
      getOriginalImg(this.config).then(res => {
        if (res && res.length) {
          this.originalImg = res[0];
        }
        if (type) {
          setTimeout(() => {
            this.getOriginalImg(true);
          }, 3000);
        }
      });
    },
    getTestingImg(cb) {
      getTestingImg(this.config).then(res => {
        if (res) {
          if (res.length) {
            this.testingImg = res[0].img;
            let text = {};
            res[0].name.forEach(_n => {
              text[this.keys[_n[0]]] = true;
            })
            this.testingText = Object.keys(text).join("，");
          } else {
            this.testingImg = "";
          }
        } 
        if (cb) {
          setTimeout(() => {
            this.getTestingImg(true);
          }, 3000);
        }
      });
    },
    // 检测统计
    getStatistics() {
      let option = {
        color: ["#ff9b15", "#1479ff", "#5337fd"],
        tooltip: {
          trigger: 'item'
        },
        legend: {
          orient: 'vertical',
          left: 'left',
        },
        title: {
          text: '检测总数',
          subtext: 0,
          textAlign: "center",
          left: '61%',
          top: "40%",
          textStyle: {
            fontSize: 14,
            fontWeight: "bold",
          },
          subtextStyle: {
            color: "#ff9b15",
            fontWeight: "bold",
            fontSize: 16,
          }
        },
        series: [
            {
              type: 'pie',
              radius: ['45%', '70%'],
              center: ["80%", "50%"],
              right: 60,
              avoidLabelOverlap: false,
              label: {
                show: false,
                position: 'center'
              },
              labelLine: {
                show: false
              },
              data: [
                  {value: 0, name: '暂无数据'},
              ]
            }
        ]
      }
      if (!this.pieEcharts) {
        this.pieEcharts = echarts.init(this.$refs.echartsPie);
        this.pieEcharts.setOption(option);
      }
      getStatistics(this.config).then(res => {
        this.statisticsInfo.time = Number(res.average_prediction_time).toFixed(2);
        this.statisticsInfo.averageScore = Number(res.average_score).toFixed(2);
        this.statisticsInfo.defectNum = res.defect_num;
        this.statisticsInfo.totalNum = res.total_num;
        option.title.subtext = res.total_num;
        option.series[0].data = [
          { value: res.defect_num, name: '缺陷个数' },
          { value: res.total_num - res.defect_num, name: '正常个数' },
        ]
        this.pieEcharts.setOption(option);
        setTimeout(() => {
          this.getStatistics();
        }, 3000);
      })
    },
    // 缺陷分布统计
    getDefectNum() {
      if (!this.defectEcharts) {
        this.defectEcharts = echarts.init(this.$refs.defect);
        this.defectEcharts.setOption(this.echartsOption);
      }
      getAllNum(this.config).then(res => {
        if (res && res.length && res[0].length) {
          let option = JSON.parse(JSON.stringify(this.echartsOption));
          let keys = Object.assign({}, this.keys);
          res[0].map(_r => {
            Object.assign(keys, _r);
          })
          option.series = [{
            data: Object.keys(keys).map(v => {
              return {
                value: keys[v],
                itemStyle: {
                  color: v === "zheng_chang" ? "#1479ff" : "#ff9b15"
                }
              }
            }),
            type: "bar",
            barWidth: 40
          }];
          this.defectEcharts.setOption(option);
        }
        
        setTimeout(() => {
          this.getDefectNum();
        }, 60000);
      })
    },
    // 当月缺陷分布
    getMonthNum() {
      if (!this.statisticsEcharts) {
        this.statisticsEcharts = echarts.init(this.$refs.statistics);
        this.statisticsEcharts.setOption(this.echartsOption);
      }
      getMonthNum(this.config).then(res => {
        if (res && res.length && res[0].length) {
          let option = JSON.parse(JSON.stringify(this.echartsOption));
          let keys = Object.assign({}, this.keys);
          res[0].map(_r => {
            Object.assign(keys, _r);
          })
          option.series = [{
            data: Object.keys(keys).map(v => {
              return {
                value: keys[v],
                itemStyle: {
                  color: v === "zheng_chang" ? "#1479ff" : "#ff9b15"
                }
              }
            }),
            type: "bar",
            barWidth: 35
          }];
          this.statisticsEcharts.setOption(option);
        }
        
        setTimeout(() => {
          this.getMonthNum();
        }, 60000);
      })
    },
    setSevenDays() {
      let currentDate = new Date();
      let year = currentDate.getFullYear();
      let mon = currentDate.getMonth() + 1;
      let day = currentDate.getDate();
      let days = [];
      let endTime = new Date(`${year}-${mon}-${day} 23:59:59`).getTime();
      for (let i = 0; i < 7; i++) {
        let time =  endTime - i * 24 * 60 * 60 * 1000;
        let date = new Date(time);
        let y = date.getFullYear();
        let m = date.getMonth() + 1;
        let d = date.getDate();
        days.unshift(`${y}-${m}-${d}`);
      }
      return days;
    },
    // 七日缺陷总量统计
    getTotalNum() {
      if (!this.totalEcharts) {
        this.totalEcharts = echarts.init(this.$refs.total);
      }
      let option = JSON.parse(JSON.stringify(this.echartsOption));
      option.xAxis.data = this.setSevenDays();
      option.series = [{
        data: [0, 0, 0, 0, 0, 0, 0],
        type: "line"
      }];
      this.totalEcharts.setOption(option);
      getDaysNum(this.config).then(res => {

        let sortKey = Object.keys(res).map(_r => {
          return {
            key: _r.replace("-", ""),
            value: _r
          }
        });
        sortKey = sortKey.sort((a, b) => a.key - b.key);
        option.xAxis.data = sortKey.map(_k =>_k.value);
        option.series = [{
          data: sortKey.map(_k => res[_k.value]),
          type: "line"
        }];
        this.totalEcharts.setOption(option);
        setTimeout(() => {
          this.getTotalNum();
        }, 60000);
      })
    }
  }
};
</script>
